import axios from 'axios';
import React, { useState, useEffect, useCallback } from 'react';
import { FixedSizeList } from 'react-window';
import InfiniteLoader from 'react-window-infinite-loader';

function ToDoList() {

    const [tasks, setTasks] = useState([]);
    const [newTask, setNewTask] = useState("");
    const [searchTerm, setSearchTerm] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [hasMore, setHasMore] = useState(true);

    const pageSize = 50;

    // ✅ Load tasks in chunks from MongoDB
    useEffect(() => {
        loadMoreTasks(0);
    }, []);

    const loadMoreTasks = async (startIndex) => {
        if (isLoading || !hasMore) return;

        setIsLoading(true);
        try {
            const response = await axios.get(`http://localhost:5001/tasks?start=${startIndex}&limit=${pageSize}`);
            if (response.data.length === 0) {
                setHasMore(false);
            } else {
                setTasks((prevTasks) => [...prevTasks, ...response.data]);
            }
        } catch (error) {
            console.error('Error loading more tasks:', error);
        }
        setIsLoading(false);
    };

    function handleSearchChange(event) {
        setSearchTerm(event.target.value);
    }

    const filteredTasks = tasks.filter(task =>
        task.text.toLowerCase().includes(searchTerm.toLowerCase())
    );

    function handleInputChange(event) {
        setNewTask(event.target.value);
    }

    // ✅ Add task to MongoDB
    async function addTask() {
        if (newTask.trim() !== "") {
            try {
                const response = await axios.post('http://localhost:5001/tasks', { text: newTask });
                setTasks((prevTasks) => [response.data, ...prevTasks]);
                setNewTask("");
            } catch (error) {
                console.error('Error adding task:', error);
            }
        }
    }

    // ✅ Delete task from MongoDB
    async function deleteTask(id) {
        try {
            await axios.delete(`http://localhost:5001/tasks/${id}`);
            setTasks((prevTasks) => prevTasks.filter(task => task._id !== id));
        } catch (error) {
            console.error('Error deleting task:', error);
        }
    }

    // ✅ Infinite loader setup
    const isItemLoaded = (index) => index < tasks.length;

    const loadMoreItems = useCallback(async (startIndex, stopIndex) => {
        if (!isLoading) {
            await loadMoreTasks(startIndex);
        }
    }, [isLoading]);

    return (
        <div className='to-do-list'>
            <h1>To-Do List</h1>

            {/* ✅ Search Bar */}
            <input
                type="text"
                placeholder="Search tasks..."
                value={searchTerm}
                onChange={handleSearchChange}
                className="search-bar"
            />

            {/* ✅ Add Task Section */}
            <div>
                <input
                    type="text"
                    placeholder="Enter a Task.."
                    value={newTask}
                    onChange={handleInputChange}
                />
                <button onClick={addTask}>Add</button>
            </div>

            {/* ✅ Infinite Loader */}
            <InfiniteLoader
                isItemLoaded={isItemLoaded}
                itemCount={hasMore ? tasks.length + 1 : tasks.length}
                loadMoreItems={loadMoreItems}
            >
                {({ onItemsRendered, ref }) => (
                    <FixedSizeList
                        height={400}
                        width="100%"
                        itemSize={50}
                        itemCount={tasks.length}
                        onItemsRendered={onItemsRendered}
                        ref={ref}
                    >
                        {({ index, style }) => {
                            if (!isItemLoaded(index)) {
                                return (
                                    <div style={style} className="loading">
                                        Loading...
                                    </div>
                                );
                            }

                            const task = tasks[index];

                            return (
                                <div style={style} className="task-item">
                                    <span>{task.text}</span>
                                    <button onClick={() => deleteTask(task._id)}>Delete</button>
                                </div>
                            );
                        }}
                    </FixedSizeList>
                )}
            </InfiniteLoader>

            {isLoading && <p className="loading-text">Loading more tasks...</p>}
        </div>
    );
}

export default ToDoList;
